import {initial,current,act,notice,readable,fullReadable,writable,story,uid,permitted,operatorPermissions,demoLogin} from './model.mjs';
let s=initial(),modal=null,menuOpen=false,listTab='all',publicFilter={q:'',category:'',location:''},resendTimer=null;
const $=x=>document.querySelector(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={list:'<path d="M8 6h12M8 12h12M8 18h12M3 6h.01M3 12h.01M3 18h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h8"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6"/>',chart:'<path d="M3 3v18h18M7 16v-4M12 16V8M17 16V5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',wifi:'<path d="M2 8a17 17 0 0 1 20 0M5 12a12 12 0 0 1 14 0M9 16a5 5 0 0 1 6 0M12 20h.01"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>'};
const icon=n=>`<span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${icons[n]||icons.file}</svg></span>`;

const permissionNames={view_queue:'Melihat antrean',view_assigned_report:'Membaca laporan tugas',claim_report:'Mengambil laporan',review_report:'Mencatat pemeriksaan',manage_followup:'Mengelola tindak lanjut',publish_report:'Mengelola publikasi',close_report:'Menutup laporan'};
const permissionFields=(selected=[])=>`<div class="field"><label>Kewenangan Operator</label>${operatorPermissions.map(v=>`<label class="checkline"><input type="checkbox" name="permissions" value="${v}" ${selected.includes(v)?'checked':''}><span>${permissionNames[v]}</span></label>`).join('')}</div>`;
const labels={FLOOD:'Banjir',FIRE:'Kebakaran',EARTHQUAKE:'Gempa bumi',ACCIDENT:'Kecelakaan',DRAFT:'Draft',PROCESSING:'Sedang dianalisis',AWAITING_CONFIRMATION:'Perlu diperiksa',READY:'Sudah dikonfirmasi',BLOCKED:'Pengiriman ditahan',FAILED:'Proses gagal',NOT_SUBMITTED:'Belum dikirim',SUBMITTED:'Menunggu Operator',ASSIGNED:'Sudah ditugaskan',IN_REVIEW:'Dalam pemeriksaan',FOLLOW_UP:'Tindak lanjut',CLOSED:'Ditutup',NOT_REVIEWED:'Belum diperiksa',VALID:'Valid',INVALID:'Tidak valid',INCONCLUSIVE:'Belum dapat dipastikan',NOT_DECIDED:'Belum diputuskan',INTERNAL:'Internal',PENDING_APPROVAL:'Persiapan publikasi',APPROVED:'Disetujui',PUBLISHED:'Terbit',CANCELLED:'Dibatalkan',PENDING:'Belum selesai',DONE:'Selesai',UNKNOWN:'Status proses belum pasti',RUNNING:'Masih diproses',SUCCEEDED:'Hasil tersimpan'};
const badge=(v,t='')=>`<span class="badge ${t||(['READY','VALID','PUBLISHED','DONE','SUCCEEDED'].includes(v)?'green':['FAILED','INVALID','BLOCKED'].includes(v)?'red':['PROCESSING','PENDING_APPROVAL','UNKNOWN','RUNNING','INCONCLUSIVE','PENDING'].includes(v)?'amber':'')}">${esc(labels[v]||v)}</span>`;
const btn=(text,a,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${a}" ${extra}>${text}</button>`;
const nav=(text,page,n)=>`<button type="button" data-action="${page==='RP02'?'new-report':'nav'}" data-page="${page}" class="${s.page===page?'active':''}">${icon(n)}${text}</button>`;
const field=(name,label,value='',opts='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" ${opts}></div>`;
const area=(name,label,value='',hint='')=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>${hint?`<span class="hint">${hint}</span>`:''}</div>`;
const short=r=>'#'+r.id.slice(-4);
const empty=(title,text,n='file')=>`<div class="empty">${icon(n)}<strong>${title}</strong>${text}</div>`;
const heading=(eyebrow,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${actions}</div>`;
const helper=(text,cls='')=>`<div class="helper ${cls}">${text}</div>`;
const stepper=step=>`<div class="stepper">${['Isi laporan','Analisis','Periksa hasil','Kirim'].map((x,i)=>`<div class="step ${i===step?'current':''}"><span class="step-num">${i+1}</span>${x}</div>`).join('')}</div>`;
function lab(){const choices=[['NORMAL','Alur normal'],['UNCERTAIN','Hasil uncertain'],['NON_EVENT','Hasil NON_EVENT'],['RUNNING','Proses RUNNING'],['UNKNOWN','Proses UNKNOWN'],['LOST_RESPONSE','Respons hilang, hasil tersimpan'],['CAPACITY_BUSY','Kapasitas penuh'],['CONFIG_NOT_READY','AI belum siap'],['INVALID_MEDIA','Berkas tidak didukung'],['CLAIM_CONFLICT','Konflik klaim'],['REVISION_CONFLICT','Konflik versi'],['OFFLINE','Offline'],['EMPTY','Daftar kosong'],['ACCESS_DENIED','Akses ditolak'],['OTP_INVALID','OTP salah'],['OTP_EXPIRED','OTP kedaluwarsa']];return `<div class="labbar"><div class="lab-brand"><strong>SLR_07 · RUANG REVIEW</strong><span>Prototype interaktif · Data contoh</span></div><div class="modes" aria-label="Pilih sudut pandang">${[['reporter','Reporter'],['operator','Operator'],['admin','Admin'],['public','Publik'],['account','Akun']].map(([v,n])=>btn(n,'role',`data-role="${v}"`,s.role===v?'active':'')).join('')}</div><div class="lab-controls"><label for="scenario">Uji keadaan</label><select id="scenario">${choices.map(([v,n])=>`<option value="${v}" ${s.scenario===v?'selected':''}>${n}</option>`).join('')}</select>${s.role==='operator'?`<select id="operator-person" aria-label="Aktor Operator contoh"><option value="op-a" ${s.operator==='op-a'?'selected':''}>Operator A</option><option value="op-b" ${s.operator==='op-b'?'selected':''}>Operator B</option></select>`:''}${s.role==='admin'?`<label><input type="checkbox" id="admin-private" ${s.adminPrivate?'checked':''}> Izin bukti privat</label>`:''}${['RUNNING','UNKNOWN'].includes(current(s)?.run?.status)?btn('Simulasi pemulihan teknis','tech-recover','','recovery-control'):''}${s.role==='account'?btn('Email contoh','demo-email'):''}${btn('Panduan','guide')}${btn('Mulai ulang','reset')}</div></div>`;}
function sidebar(){let items='';if(s.role==='reporter')items=nav('Laporan Saya','RP01','list')+nav('Buat Laporan','RP02','plus')+nav('Notifikasi','UM01','bell')+nav('Profil','AK07','user');if(s.role==='operator')items=nav('Antrean Laporan','OP01','list')+nav('Laporan Saya','OP02','file')+nav('Notifikasi','UM01','bell')+nav('Profil','AK07','user');if(s.role==='admin')items=nav('Monitoring Laporan','AD02','chart')+nav('Akun Operator','AD01','user')+nav('Audit','AD03','shield')+nav('Monitoring Layanan','AD04','chart')+nav('Notifikasi','UM01','bell')+nav('Profil','AK07','user');if(s.role==='public')items=nav('Daftar Kejadian','PB01','globe')+nav('Tentang SILAR','ABOUT','file')+nav('Masuk','AK01','user');if(s.role==='account')items=nav('Masuk','AK01','user')+nav('Daftar Reporter','AK02','plus')+nav('Verifikasi Email','AK03','shield')+nav('Aktivasi Operator','AK04','shield')+nav('Lupa Password','AK05','lock');return `<aside class="sidebar"><div><div class="wordmark"><span class="mark">≋</span>SILAR</div><div class="brand-sub">PELAPORAN KEJADIAN<br>TERSTRUKTUR</div></div><div><div class="nav-label">${{reporter:'Ruang Pelapor',operator:'Ruang Operator',admin:'Ruang Admin',public:'Informasi Publik',account:'Akun dan Akses'}[s.role]}</div><nav class="nav-links" aria-label="Navigasi utama">${items}</nav></div>${s.role!=='public'&&s.role!=='account'?`<div><div class="nav-label">Jelajahi</div><nav class="nav-links">${nav('Kejadian Publik','PB01','globe')}${nav('Instalasi dan Koneksi','UM02','wifi')}</nav></div>`:''}<div class="sidebar-bottom"><div class="sidebar-user"><div class="user-avatar">${{reporter:'PC',operator:'OP',admin:'AD',public:'PU',account:'AK'}[s.role]}</div><div><strong>${{reporter:esc(s.accountName),operator:s.operator==='op-a'?'Operator A':'Operator B',admin:'Admin Contoh',public:'Pembaca Publik',account:'Akun Contoh'}[s.role]}</strong>Data simulasi</div></div>${['reporter','operator','admin'].includes(s.role)?btn('Keluar','logout','','link'):''}<br>Semua perubahan pada prototype hanya berlangsung dalam sesi ini.</div></aside>`;}
function reportRows(reports,mode){if(!reports.length||s.scenario==='EMPTY')return empty(mode==='queue'?'Antrean sedang kosong':'Belum ada laporan','Laporan yang sesuai akan tampil di sini.');return `<div class="table-scroll"><table><thead><tr><th>LAPORAN</th><th>KATEGORI</th><th>${mode==='owned'?'KESIAPAN':'PENANGANAN'}</th><th>WAKTU</th><th>TINDAKAN</th></tr></thead><tbody>${reports.map(r=>`<tr><td><strong>${short(r)}</strong><div class="small-text">${r.workflow==='NOT_SUBMITTED'?'Draft online':'Laporan resmi'}</div></td><td>${r.card?.category?labels[r.card.category]:'Belum dianalisis'}${r.card?.uncertain?'<div class="small-text">Perlu perhatian · uncertain</div>':''}</td><td>${badge(mode==='owned'&&r.workflow==='NOT_SUBMITTED'?r.preparation:r.workflow)}</td><td class="no-wrap">${r.submittedAt||r.createdAt}</td><td>${mode==='queue'?btn('Ambil Laporan','claim',`data-id="${r.id}"`,'small'):btn(r.workflow==='NOT_SUBMITTED'?'Lanjutkan':'Buka Detail','open-report',`data-id="${r.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>${reports.length} laporan contoh · Daftar ringkas</span><span>Halaman 1 dari 1</span></div>`;}
function listPage(mode){if(s.role==='operator'&&!permitted(s,mode==='queue'?'view_queue':'view_assigned_report'))return denied();const owned=mode==='owned',queue=mode==='queue';let reports=s.reports.filter(r=>owned?r.owner==='reporter':queue?r.workflow==='SUBMITTED'&&!r.assignee:r.assignee===s.operator);if(owned&&listTab==='draft')reports=reports.filter(r=>r.workflow==='NOT_SUBMITTED');if(owned&&listTab==='submitted')reports=reports.filter(r=>r.workflow!=='NOT_SUBMITTED');return heading(owned?'Ruang Pelapor':'Ruang Operator',queue?'Antrean Laporan':'Laporan Saya',owned?'Simpan draft, periksa hasil, dan pantau perkembangan laporan Anda.':queue?'Ambil laporan yang belum memiliki penanggung jawab. Detail dibuka setelah penugasan sah.':'Laporan yang menjadi tanggung jawab Anda, termasuk riwayat yang telah ditutup.',owned?btn('+ Buat Laporan','new-report','','primary'):'')+`${owned?`<div class="tabs">${[['all','Semua'],['draft','Draft'],['submitted','Sudah Dikirim']].map(([v,n])=>btn(n,'tab',`data-tab="${v}"`,listTab===v?'active':'')).join('')}</div>`:queue?helper('Ringkasan antrean tidak memuat identitas, alamat privat, narasi, atau bukti laporan.'):''}<div class="card">${reportRows(reports,mode)}</div>`;}
function evidence(r,selectable=false){return r.evidence.length? r.evidence.map(e=>`<div class="evidence-row">${selectable?`<input type="checkbox" aria-label="Pilih ${esc(e.name)} untuk analisis" data-evidence="${e.id}" ${r.selected.includes(e.id)?'checked':''}>`:''}${e.preview?`<img src="${esc(e.preview)}" alt="Pratinjau gambar yang dipilih">`:`<span class="type-icon">${{TEXT:'TXT',AUDIO:'AUD',IMAGE:'IMG'}[e.type]}</span>`}<div><strong>${esc(e.name)}</strong><p>${e.type==='TEXT'?esc(e.text):`${esc(e.mime||'Format diperiksa saat integrasi')} · ${Math.ceil((e.size||0)/1024)} KB`}</p>${badge('Tersimpan','green')}${r.bundle?.items.includes(e.id)?' <span class="hint">Dalam bundle aktif</span>':''}</div></div>`).join(''):empty('Belum ada bukti tersimpan','Tambahkan sumber, kemudian pilih Simpan Draft.');}
function compose(){const r=current(s);if(s.role!=='reporter'||!readable(s,r))return denied();if(r.workflow!=='NOT_SUBMITTED')return detail();return heading('Pelaporan Multimodal','Buat Laporan','Ceritakan kejadian dengan teks, suara, gambar, atau kombinasinya.',`<span class="version-tag">${short(r)} · ${r.bundle?'Draft tersimpan':'Belum tersimpan'}</span>`)+stepper(0)+`<div class="grid"><section><div class="card"><div class="card-header"><div><h2>Ceritakan kejadian</h2><p>Sampaikan fakta yang Anda ketahui. Informasi yang belum diketahui boleh dibiarkan.</p></div>${btn('Gunakan contoh','sample','','small quiet')}</div><div class="field"><label for="report-text">Cerita Anda</label><textarea id="report-text" class="story" placeholder="Contoh: Banjir di Jalan Melati sejak pagi. Air mulai masuk rumah…">${esc(r.text)}</textarea><span class="hint">Cakupan: kebakaran, banjir, gempa bumi, dan kecelakaan. Kategori akan dikenali melalui analisis.</span></div><div class="channel-grid"><div class="channel">${icon('mic')}<h3>Suara</h3><p>Rekam atau pilih audio ketika lebih mudah daripada mengetik.</p>${btn('Rekam Suara','record','','small')}${btn('Unggah Audio','pick-audio','','small')}<input class="file-input" id="audio-file" type="file" accept="audio/*"></div><div class="channel">${icon('image')}<h3>Gambar</h3><p>Tambahkan gambar PNG atau JPEG yang relevan dengan kejadian.</p>${btn('Tambah Gambar','pick-image','','small')}<input class="file-input" id="image-file" type="file" accept="image/png,image/jpeg" multiple></div></div>${r.pendingFiles.length?helper(`${r.pendingFiles.length} media dipilih dan belum disimpan dalam draft.`,'amber'):''}${helper('Gunakan bukti yang menjadi hak Anda untuk disampaikan. Hindari identitas dan informasi pribadi yang tidak diperlukan.')}<div class="actions"><span class="hint">Simpan sumber sebelum menjalankan analisis. Tidak ada penyimpanan draft offline.</span>${btn('Simpan Draft','save')}${btn('Analisis Laporan '+icon('arrow'),'analyse','','primary')}</div></div></section><aside><div class="card"><div class="card-header"><div><h2>Bukti laporan</h2><p>Pilih sumber yang digunakan dalam analisis.</p></div><span class="version-tag">${r.evidence.length} item</span></div>${evidence(r,true)}${r.bundle?helper(`Bundle ${r.bundle.version} menyimpan pilihan sumber. Mengubah pilihan perlu disimpan sebagai bundle baru.`):''}</div><div class="card"><h2>Sebelum analisis</h2><p class="subtitle">Teks saja diproses lokal. Audio ditranskripsikan lokal. Gambar atau gabungan kanal menggunakan layanan AI eksternal Gemini untuk membentuk narasi.</p><p class="hint">Teks, transkrip, atau gambar yang relevan dapat dikirim sesuai rute. Audio asli tetap diproses lokal. Minimisasi data bukan jaminan seluruh bukti anonim.</p></div></aside></div>`;}
function processPage(){const r=current(s);const pendingRevision=!!r.correctedNarrative&&!r.card&&r.run?.inputRevision!==r.inputRevision&&!['RUNNING','UNKNOWN'].includes(r.run?.status);const run=pendingRevision?null:r.run;if(s.role!=='reporter'||!readable(s,r))return denied();const lost=r.clientLost;return heading('Analisis Laporan',lost?'Respons belum diterima':run?.status==='UNKNOWN'?'Hasil proses belum dapat dipastikan':'Pemrosesan laporan','Keadaan tampilan mengikuti rekaman yang tersimpan. Menutup tab tidak menjamin proses tetap berjalan.')+stepper(1)+`<div class="process"><div class="card process-main"><div class="process-icon">${icon('clock')}</div><h2>${lost?'Periksa hasil tersimpan':run?labels[run.status]:'Narasi revisi siap dianalisis'}</h2><p class="subtitle">${lost?'Respons sebelumnya hilang. Periksa status untuk menemukan hasil tanpa mengulang analisis.':run?.status==='UNKNOWN'?'Analisis baru ditahan sampai keadaan eksekusi dipastikan dan pemulihan teknis disahkan.':run?.status==='FAILED'?'Periksa penyebab kegagalan sebelum mencoba kembali secara eksplisit.':'Prototype memperagakan keadaan proses menggunakan data contoh.'}</p>${run&&['RUNNING','UNKNOWN'].includes(run.status)?'<div class="process-wait" aria-label="Menunggu hasil"><span></span><span></span><span></span></div>':''}<ul class="process-list"><li><span class="dot"></span> Bukti dan sumber tersimpan</li><li><span class="dot active"></span> Narasi, klasifikasi, dan ekstraksi</li><li><span class="dot"></span> Penyimpanan hasil sebelum konfirmasi</li></ul>${run?badge(run.status):''}${run?.error?helper(esc(run.error),'red'):''}<div class="actions">${btn('Kembali ke Input','nav',`data-page="RP02"`)}${run?btn('Periksa Status','read-status','','primary'):btn('Analisis Narasi Revisi','analyse-revision','','primary')}${run?.status==='FAILED'?btn('Coba Analisis Lagi',run.mode==='NARRATIVE_REVISION'?'analyse-revision':'analyse','','primary'):''}</div><p class="metric-note">Indikator ini tidak menyatakan persentase, estimasi waktu, atau performa layanan nyata.</p></div></div>`;}
function cardFields(c){return `<dl class="detail-list">${[['Jenis kejadian',labels[c.category]||'Belum dikenali sebagai kejadian dalam cakupan'],['Lokasi',c.location],['Waktu yang disebut',c.time],['Waktu pasti',c.occurredAt],['Pihak terlibat',c.parties],['Dampak',c.impact],['Informasi korban',c.victims],['Objek terdampak',c.objects]].map(([n,v])=>`<div><dt>${n}</dt><dd>${v?esc(v):'<span class="unknown">Belum tersedia</span>'}</dd></div>`).join('')}</dl>`;}
function verify(){const r=current(s),c=r.card;if(s.role!=='reporter'||!readable(s,r))return denied();if(!c)return compose();if(r.workflow!=='NOT_SUBMITTED')return detail();return heading('Human Verification','Periksa hasil laporan','Bandingkan sumber dengan hasil. Konfirmasi berarti Anda telah memeriksa versi ini, bukan verifikasi kejadian di lapangan.',`<span class="version-tag">Versi ${c.version}</span>`)+stepper(2)+(!c.category?helper('<strong>Pengiriman ditahan · NON_EVENT.</strong> Hasil AI belum mengenali narasi sebagai laporan kejadian dalam cakupan. Periksa narasi dan minta analisis ulang. Ini bukan pernyataan bahwa Pelapor berbohong.','red'):'')+(c.uncertain?helper('<strong>Perlu perhatian · uncertain.</strong> Keyakinan klasifikasi contoh rendah. Periksa hasil dan informasi yang belum pasti. Penanda tetap ada setelah konfirmasi.','amber'):'')+`<div class="grid equal"><div class="card source-panel"><div class="card-header"><div><h2>Sumber laporan</h2><p>Bukti asli dipertahankan untuk perbandingan.</p></div>${btn('Kembali ke Input','nav','data-page="RP02"','small')}</div>${evidence(r)}<details><summary>Transkrip dan sumber turunan</summary><p>${r.evidence.some(e=>e.type==='AUDIO')?'Transkrip contoh tersedia setelah pemrosesan. Periksa kembali terhadap audio asli.':'Tidak ada kanal audio pada bundle ini.'}</p></details></div><div><div class="card"><div class="card-header"><div><h2>Narasi hasil pengolahan</h2><p>Perubahan narasi memerlukan analisis ulang.</p></div>${btn('Ubah Narasi','edit-narrative','','small')}</div><div class="narrative">${esc(c.narrative)}</div></div><div class="card"><div class="card-header"><div><h2>Incident Card</h2><p>Informasi yang tidak ditemukan tetap belum tersedia.</p></div>${btn('Koreksi Informasi','edit-fields','','small')}</div>${cardFields(c)}<details><summary>Informasi analisis AI</summary><p>Keyakinan klasifikasi contoh: ${Math.round(c.confidence*100)}%. Angka ini tidak menunjukkan kepastian kejadian di lapangan.</p><p>Kategori berasal dari SENA. Ekstraksi informasi berasal dari NARA. Keduanya diperagakan menggunakan data contoh.</p></details></div></div></div><div class="card"><h2>Konfirmasi dan pengiriman</h2><p class="subtitle">Pastikan informasi sesuai dengan sumber dan pengetahuan Anda. Informasi yang tidak diketahui tidak perlu ditebak.</p>${r.confirmed===c.version?helper(`Versi ${c.version} sudah dikonfirmasi. Laporan belum dikirim.`,'green'):''}<div class="actions"><span class="hint">Setelah pengiriman berhasil, versi resmi dikunci dan masuk antrean Operator.</span>${btn('Konfirmasi Versi Ini','confirm',(!c.category||r.confirmed===c.version)?'disabled':'')}${btn('Kirim Laporan','submit',(!c.category||r.confirmed!==c.version)?'disabled':'','primary')}</div></div>`;}
function statusGrid(r){return `<div class="status-grid">${[['Kesiapan',r.preparation],['Penanganan',r.workflow],['Pemeriksaan',r.validation],['Publikasi',r.publication]].map(([n,v])=>`<div class="status-box"><span>${n}</span>${badge(v)}</div>`).join('')}</div>`;}
function detail(){const r=current(s);if(!r||!readable(s,r))return denied();const full=fullReadable(s,r),op=s.role==='operator',can=writable(s,r);return heading(s.role==='admin'?'Monitoring Baca Saja':op?'Penanganan Operator':'Laporan Resmi',`Detail laporan ${short(r)}`,'Konfirmasi Reporter, pemeriksaan Operator, publikasi, dan penutupan memiliki keadaan yang berbeda.',r.workflow==='CLOSED'?badge('CLOSED'):'')+statusGrid(r)+`<div class="grid"><div><div class="card"><div class="card-header"><div><h2>Versi resmi ${r.officialVersion||'—'}</h2><p>${full?'Isi laporan dan hasil mentah tidak disunting melalui penanganan.':'Izin monitoring hanya membuka ringkasan administratif.'}</p></div>${icon('lock')}</div>${full&&r.card?`<div class="narrative">${esc(r.card.narrative)}</div>${cardFields(r.card)}`:helper('Narasi, bukti, dan isi Incident Card tidak ditampilkan karena akses isi privat belum diberikan.')}<p class="hint">${r.confirmed?'Konfirmasi Reporter tercatat untuk versi resmi.':'Belum ada konfirmasi versi resmi.'}</p></div>${full?`<div class="card"><h2>Bukti dan riwayat versi</h2>${r.evidence.length?evidence(r):helper('Pada fixture ini, sumber contoh ditampilkan sebagai narasi. Alur draft menyediakan daftar bukti dan bundle.')}${r.card?.uncertain?helper('Penanda uncertain tetap tersedia untuk pemeriksaan.','amber'):''}<details><summary>Lihat riwayat tindakan</summary><ul class="timeline">${r.history.length?r.history.map(h=>`<li>${esc(h.action)}<small>${h.at} · revisi ${h.revision}</small></li>`).join(''):'<li>Versi resmi dikirim oleh Reporter.<small>Data contoh</small></li>'}</ul></details></div>`:''}</div><aside><div class="card"><h2>Hasil pemeriksaan</h2>${r.review?`${badge(r.review.outcome)}${op||s.role==='admin'&&s.adminPrivate?`<p class="subtitle">${esc(r.review.reason)}</p>`:'<p class="hint">Alasan internal tidak dibuka pada tampilan Reporter.</p>'}`:helper('Operator belum mencatat hasil pemeriksaan.')}${op&&can?`<div class="actions">${btn('Catat Pemeriksaan','review',r.publicVersion?'disabled':'','primary')}</div>${r.publicVersion?'<p class="hint">Hasil review dikunci setelah publikasi pertama.</p>':''}`:''}</div>${full&&(op||s.role==='admin')?`<div class="card"><div class="card-header"><h2>Tindak lanjut</h2>${op&&can?btn('+ Catat','followup',!r.review?'disabled':'','small'):''}</div>${r.followups.length?r.followups.map(f=>`<div class="evidence-row"><div><strong>${esc(f.description)}</strong><p>${badge(f.status)}</p>${op&&can&&f.status==='PENDING'?`<div class="inline-actions">${btn('Selesai','finish-followup',`data-id="${f.id}" data-status="DONE"`,'small')}${btn('Batalkan','finish-followup',`data-id="${f.id}" data-status="CANCELLED"`,'small')}</div>`:''}</div></div>`).join(''):'<p class="hint">Belum ada tindak lanjut tercatat.</p>'}</div>`:''}${op?`<div class="card"><h2>Keputusan berikutnya</h2><p class="hint">Tindakan mengikuti hasil pemeriksaan dan penugasan saat ini.</p><div class="inline-actions">${btn('Internal / Publikasi','decision',!can||!r.review?'disabled':'')}${btn('Kandidat Publikasi','nav',`data-page="OP05" ${!can?'disabled':''}`)}${btn('Tutup Laporan','close',!can?'disabled':'')}</div></div>`:''}${s.role==='admin'?`<div class="card"><h2>Penanggung jawab</h2><p class="subtitle">${r.assignee?esc(r.assignee==='op-a'?'Operator A':'Operator B'):'Belum ditugaskan'}</p><div class="actions">${btn('Tugaskan / Alihkan','assign',r.workflow==='CLOSED'?'disabled':'')}</div></div>`:''}</aside></div>`;}
function publicForm(data={}){return area('summary','Ringkasan publik',data.summary||'')+field('general_location','Lokasi umum',data.general_location||'')+field('time_text','Waktu yang aman ditampilkan',data.time_text||'')+area('general_impact','Dampak umum',data.general_impact||'')+area('handling_update','Perkembangan penanganan',data.handling_update||'');}
function publication(){const r=current(s);if(s.role!=='operator'||!readable(s,r))return denied();const c=r.candidate,old=r.publicVersion;return heading('Sanitasi dan Publikasi','Siapkan informasi publik','Periksa nama, kontak, alamat privat, tuduhan tanpa dukungan, serta kombinasi informasi yang dapat mengidentifikasi pihak.',btn('Kembali ke Laporan','nav','data-page="OP03"','small'))+statusGrid(r)+(old?helper('Versi publik '+old.version+' tetap tampil selama kandidat pengganti disiapkan atau dibatalkan.','green'):'')+`<div class="grid equal"><div class="card"><div class="card-header"><div><h2>${c?'Kandidat versi '+c.version:'Bentuk kandidat baru'}</h2><p>${c?'Isi versi tersimpan tidak disunting langsung.':'Data berikut menjadi representasi publik, terpisah dari laporan internal.'}</p></div>${c?badge(c.state):badge('Belum dibuat')}</div>${c?publicPreview(c.data):`<form id="publication-form">${publicForm(old?.data||{summary:r.card?.narrative||'',general_location:'',time_text:r.card?.time||'',general_impact:r.card?.impact||'',handling_update:''})}<div class="actions"><span class="hint">Kategori tetap mengikuti versi resmi.</span><button class="primary" ${r.publication!=='PENDING_APPROVAL'||r.workflow==='CLOSED'?'disabled':''}>Buat Kandidat</button></div></form>`}${!c&&r.publication!=='PENDING_APPROVAL'?helper('Tetapkan arah PREPARE pada keputusan publikasi sebelum membentuk kandidat.','amber'):''}</div><div class="card"><h2>Pemeriksaan versi tepat</h2><p class="subtitle">Allowlist membantu membatasi field. Operator tetap memeriksa isi dan kemungkinan identifikasi dari gabungan field.</p>${c?`<label class="checkline"><input type="checkbox" id="sanitization-check" ${s.publicationChecked?'checked':''} ${c.state!=='DRAFT'?'disabled':''}><span>Saya sudah memeriksa isi dan sanitasi kandidat versi ${c.version} yang ditampilkan.</span></label><div class="actions">${btn('Batalkan Kandidat','cancel-candidate',r.workflow==='CLOSED'?'disabled':'','danger')}${c.state==='DRAFT'?btn('Setujui Versi Ini','approve',!s.publicationChecked||r.workflow==='CLOSED'?'disabled':'','primary'):btn('Terbitkan','publish',r.workflow==='CLOSED'?'disabled':'','primary')}</div><p class="hint">Persetujuan belum berarti terbit. Perubahan isi memerlukan pembatalan kandidat aktif dan pembuatan versi baru.</p>`:helper('Belum ada kandidat aktif untuk diperiksa.')}<details><summary>Penutupan dan pembatalan</summary><p>Pembatalan berlaku untuk kandidat DRAFT atau APPROVED. Versi yang sudah terbit tidak ditarik melalui tindakan ini. Laporan CLOSED menolak perubahan publikasi.</p></details></div></div>`;}
function publicPreview(d){return `<dl class="detail-list">${[['Jenis kejadian',labels[d.event_type]||'Mengikuti versi resmi'],['Ringkasan',d.summary],['Lokasi umum',d.general_location],['Waktu kejadian',d.time_text],['Dampak umum',d.general_impact],['Perkembangan',d.handling_update]].map(([n,v])=>`<div><dt>${n}</dt><dd>${v?esc(v):'<span class="unknown">Belum tersedia</span>'}</dd></div>`).join('')}</dl>`;}
function publicList(){let rs=s.reports.filter(r=>r.publicVersion);if(publicFilter.category)rs=rs.filter(r=>r.publicVersion.data.event_type===publicFilter.category);if(publicFilter.location)rs=rs.filter(r=>(r.publicVersion.data.general_location||'').toLowerCase().includes(publicFilter.location.toLowerCase()));if(publicFilter.q)rs=rs.filter(r=>['summary','general_location','general_impact','handling_update'].some(k=>(r.publicVersion.data[k]||'').toLowerCase().includes(publicFilter.q.toLowerCase())));return heading('Portal Publik','Informasi kejadian','Informasi berasal dari laporan yang ditinjau berdasarkan bukti tersedia. Tidak menyatakan verifikasi kejadian di lapangan.')+`<form id="public-filter" class="card filters">${field('q','Cari informasi',publicFilter.q,'placeholder="Ringkasan, lokasi, dampak…"')}<div class="field"><label for="pub-category">Kategori</label><select id="pub-category" name="category"><option value="">Semua kategori</option>${['FLOOD','FIRE','EARTHQUAKE','ACCIDENT'].map(v=>`<option value="${v}" ${publicFilter.category===v?'selected':''}>${labels[v]}</option>`).join('')}</select></div>${field('location','Lokasi umum',publicFilter.location,'placeholder="Kawasan atau jalan umum"')}<button class="primary">Cari</button></form><p class="hint">Diurutkan berdasarkan publikasi terbaru. Pencarian hanya menggunakan field publik.</p><div class="public-grid">${rs.length&&s.scenario!=='EMPTY'?rs.slice().sort((a,b)=>(b.publicVersion.publishedOrder||0)-(a.publicVersion.publishedOrder||0)).map(r=>`<article class="card public-card">${badge(r.publicVersion.data.event_type,'blue')}<h2>${esc(r.publicVersion.data.general_location||labels[r.publicVersion.data.event_type])}</h2><p>${esc(r.publicVersion.data.summary)}</p><div class="public-meta"><span>Terbit: ${r.publicVersion.publishedAt}</span><span>Kejadian: ${esc(r.publicVersion.data.time_text||'Belum tersedia')}</span></div>${btn('Baca Informasi '+icon('arrow'),'nav',`data-page="PB02" data-id="${r.id}"`,'link')}</article>`).join(''):`<div class="card">${empty('Tidak ada informasi yang sesuai','Sesuaikan pencarian atau filter Anda.','search')}</div>`}</div>`;}
function publicDetail(){const r=current(s);if(!r?.publicVersion)return denied();return heading('Informasi Publik',labels[r.publicVersion.data.event_type],`Diterbitkan ${esc(r.publicVersion.publishedAt)}`,btn('Kembali ke Daftar','nav','data-page="PB01"','small'))+`<div class="card">${publicPreview(r.publicVersion.data)}${helper('Informasi bersumber dari laporan yang ditinjau berdasarkan bukti tersedia. Identitas, bukti asli, dan catatan internal tidak ditampilkan.')}<p class="hint">Informasi yang sudah dipublikasikan dapat disalin di luar aplikasi.</p></div>`;}
function notifications(){let ns=s.notifications.filter(n=>n.role===s.role&&(s.role!=='operator'||n.operator===s.operator));return heading('Pemberitahuan','Notifikasi','Perkembangan yang relevan tersedia di dalam aplikasi. Daftar dimuat ketika halaman dibuka atau disegarkan.',btn('Segarkan','refresh','','small'))+`<div class="card">${ns.length&&s.scenario!=='EMPTY'?ns.map(n=>`<div class="notification">${icon('bell')}<div class="body"><strong>${esc(n.kind)}</strong><p>${esc(n.message)}</p><small>Data contoh · ${s.notificationRead.includes(n.id)?'Sudah dibaca':'Belum dibaca'}</small></div><div class="inline-actions">${btn('Buka','open-notification',`data-id="${n.id}"`,'small')}${!s.notificationRead.includes(n.id)?btn('Tandai dibaca','mark-read',`data-id="${n.id}"`,'small'):''}</div></div>`).join(''):empty('Belum ada notifikasi','Notifikasi yang relevan akan tampil di sini.','bell')}</div>`;}
function auth(){const p=s.page;if(p==='AK07')return heading('Akun','Profil Saya','Perubahan profil mengikuti field yang diizinkan.')+`<form id="profile-form" class="card" style="max-width:600px">${field('name','Nama',s.accountName)}${field('email','Email',s.accountEmail||demoLogin.email,'readonly')}${field('role','Peran',{reporter:'Reporter',operator:'Operator',admin:'Admin'}[s.role]||'Reporter','readonly')}<div class="actions"><button class="primary">Simpan Nama</button></div></form>`;
 const title={AK01:'Masuk ke SILAR',AK02:'Daftar sebagai Pelapor',AK03:'Verifikasi email',AK04:'Aktivasi akun Operator',AK05:'Pulihkan akses akun',AK06:'Tetapkan password baru'}[p]||'Masuk';const otp=['AK03','AK04','AK06'].includes(p),pw=['AK01','AK02','AK04','AK06'].includes(p);return `<div class="auth-wrap"><div class="eyebrow">Akun dan Akses</div><div class="card"><h1>${title}</h1><p class="subtitle">${otp?'Gunakan kode dari email terbaru dan halaman yang dibuka melalui tautan email.':'Gunakan akun Anda untuk mengakses fungsi sesuai kewenangan.'}</p><div class="account-demo">Area demonstrasi akun. Gunakan data contoh; jangan masukkan password asli. Kode uji tersedia pada panduan review.${p==='AK01'?`<br>Akun awal contoh: <strong>${esc(demoLogin.email)}</strong> · password <strong>${esc(demoLogin.password)}</strong>. Akun yang baru didaftarkan memakai password pendaftaran setelah verifikasi; sesudah reset gunakan password baru.`:''}</div>${s.accountMessage?helper(esc(s.accountMessage),'green'):''}<form id="auth-form">${p==='AK02'?field('name','Nama lengkap','','required autocomplete="off"'):''}${!otp?field('email','Email',s.accountEmail||demoLogin.email,'type="email" required autocomplete="off"'):''}${otp?field('code','Kode OTP enam digit','','class="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"'):''}${pw?field('password',p==='AK01'?'Password':'Password baru','','type="password" required autocomplete="off"'):''}${['AK02','AK04','AK06'].includes(p)?field('password_confirm','Konfirmasi password','','type="password" required autocomplete="off"'):''}<button class="primary">${{AK01:'Masuk',AK02:'Daftar',AK03:'Verifikasi Email',AK04:'Aktifkan Akun',AK05:'Kirim Petunjuk Pemulihan',AK06:'Simpan Password Baru'}[p]}</button></form><div class="auth-links">${btn(p==='AK01'?'Daftar Reporter':'Kembali ke Masuk','nav',`data-page="${p==='AK01'?'AK02':'AK01'}"`,'link')}${p==='AK01'?btn('Lupa password?','nav','data-page="AK05"','link'):otp?(p==='AK04'?'<span class="hint">Hubungi Admin untuk pengiriman ulang aktivasi.</span>':btn(s.resendSeconds>0?'Kirim ulang dalam '+s.resendSeconds+' dtk':'Kirim ulang kode','resend',s.resendSeconds>0?'disabled':'','link')):''}</div>${helper('Jaga kerahasiaan password dan OTP. Petugas tidak meminta kode Anda. Cookie autentikasi diperlukan agar akses akun dapat berfungsi.')}<p class="hint">Gunakan email terbaru setelah pengiriman ulang. Kode sebelumnya tidak berlaku.</p></div></div>`;}
function admin(){
 if(s.role!=='admin')return denied();
 if(s.page==='AD02')return heading('Administrasi','Monitoring Laporan','Pantau laporan resmi dan kelola penugasan sesuai izin. Draft Reporter tidak tersedia.')+`<div class="card">${reportRows(s.reports.filter(r=>r.workflow!=='NOT_SUBMITTED'),'admin')}</div>`;
 if(s.page==='AD01')return heading('Administrasi','Akun Operator','Admin mengelola akun dan izin. Password ditetapkan sendiri oleh pemilik saat aktivasi.',btn('+ Buat Operator','new-operator','','primary'))+`<div class="card"><div class="table-scroll compact"><table><thead><tr><th>AKUN</th><th>AKTIVASI</th><th>KEWENANGAN</th><th>TINDAKAN</th></tr></thead><tbody>${s.operators.map(o=>`<tr><td><strong>${esc(o.name)}</strong><div class="small-text">${esc(o.email)}</div></td><td>${badge(!o.verified?'Belum aktivasi':o.active?'Aktif':'Nonaktif',o.verified&&o.active?'green':'amber')}</td><td>${o.permissions.length} izin Operator</td><td><div class="inline-actions">${btn('Kelola','manage-operator',`data-id="${o.id}"`,'small')}${!o.verified?btn('Kirim Aktivasi','resend-activation',`data-id="${o.id}"`,'small'):''}</div></td></tr>`).join('')}</tbody></table></div><p class="hint">Penonaktifan tidak menghapus riwayat. Akun yang belum diaktivasi tidak diaktifkan melalui pengelolaan ini.</p></div>`;
 if(s.page==='AD03')return heading('Administrasi','Audit Aktivitas','Proyeksi tindakan yang diizinkan. Bukti, OTP, token, dan rahasia tidak menjadi isi audit.')+`<div class="card"><div class="table-scroll compact"><table><thead><tr><th>LAPORAN</th><th>TINDAKAN</th><th>REVISI</th><th>WAKTU</th></tr></thead><tbody>${s.reports.flatMap(r=>r.history.map(h=>`<tr><td>${short(r)}</td><td>${esc(h.action)}</td><td>${h.revision}</td><td>${h.at}</td></tr>`)).join('')||'<tr><td colspan="4">Belum ada tindakan pada sesi prototype ini.</td></tr>'}</tbody></table></div></div>`;
 return heading('Administrasi','Monitoring Layanan','Status dan metadata contoh. Panel ini tidak menyediakan kendali menjalankan ulang model.')+`<div class="info-grid">${[['Layanan API','READY'],['Pipeline AI',s.scenario==='CONFIG_NOT_READY'?'NOT_CONFIGURED':'READY'],['Media privat','READY'],['Layanan email','READY']].map(([n,v])=>`<div class="card"><h2>${n}</h2>${badge(v,v==='READY'?'green':'amber')}<p class="hint">Keadaan fixture · bukan hasil pemeriksaan server nyata.</p></div>`).join('')}</div>${helper('Kapasitas, waktu proses, dan ketersediaan model produksi harus berasal dari pengukuran. Tidak ada estimasi kapasitas nyata pada prototype ini.')}`;
}
function pwaPage(){return heading('Akses Aplikasi','Instalasi dan koneksi','SILAR menggunakan antarmuka yang sama pada browser dan PWA.')+`<div class="card"><h2>Pasang SILAR pada perangkat</h2><p class="subtitle">Gunakan fasilitas instalasi browser ketika tersedia. Tampilan dasar dapat dibuka setelah aset antarmuka tersimpan.</p><div class="actions">${btn('Lihat Panduan Instalasi','install-demo','','primary')}</div>${helper('Draft, bukti, hasil AI, dan seluruh operasi laporan membutuhkan koneksi. Tidak ada sinkronisasi draft offline.')}</div>`;}
function offline(){return heading('Koneksi','Anda sedang offline','Operasi laporan membutuhkan koneksi. Aset antarmuka yang pernah dimuat dapat tersedia sesuai kemampuan PWA.')+`<div class="card">${empty('Sambungkan kembali ke internet','Draft, bukti, hasil AI, dan token tidak disimpan pada cache offline.','wifi')}${helper('Pada prototype, matikan skenario Offline melalui kontrol review untuk melanjutkan. Tidak ada sinkronisasi draft latar belakang.','amber')}</div>`;}
function denied(){return heading('Akses','Informasi tidak tersedia','Halaman atau tindakan tidak tersedia untuk akun dan kewenangan saat ini.')+`<div class="card">${empty('Akses dibatasi','Kembali ke daftar yang dapat Anda akses.','shield')}${btn('Kembali ke Daftar','role',`data-role="${s.role==='account'?'reporter':s.role}"`)}</div>`;}
function guide(){return heading('Pedoman Review','Wireframe SILAR SLR_07','Alur contoh untuk memeriksa antarmuka dan keputusan pengguna.',`<a href="https://silar-slr07-wireframe.ntesengmajola699.chatgpt.site/SLR_07_UIUX_SILAR_Siap_Dipindahkan.zip" download>Sumber yang dapat diedit ↓</a>`)+`<div class="card readme"><h2>Cara mencoba</h2><ol><li>Reporter → Buat Laporan → Gunakan contoh → Simpan Draft → Analisis → Konfirmasi → Kirim.</li><li>Operator → Antrean → Ambil Laporan → Catat Pemeriksaan → tentukan internal atau siapkan publikasi.</li><li>Untuk publikasi: PREPARE → Buat Kandidat → Periksa Sanitasi → Setujui → Terbitkan. Close tetap tindakan terpisah.</li><li>Ganti sudut pandang Admin untuk penugasan, audit, akun Operator, dan monitoring.</li><li>Gunakan pilihan keadaan pada bar review untuk NON_EVENT, uncertain, respons hilang, konflik, dan offline.</li></ol><h2>Batas prototype</h2><p>Interaksi menggunakan state dalam memori dan data contoh. Tidak ada koneksi API, model AI, pengiriman email, unggah server, akses mikrofon, atau pemasangan PWA nyata. Refresh halaman mengembalikan fixture awal. Alur pemulihan memperagakan pembacaan backend; tidak benar-benar membaca server.</p><p>Sumber HTML/CSS/JavaScript ini adalah sarana prototype. Implementasi frontend SILAR tetap mengikuti keputusan Vue 3, Vite, Vue Router, Fetch dan CSS.</p><h2>Pemeriksaan akun</h2><p>Kode OTP fixture adalah 123456. Login awal memakai pelapor@contoh.test dengan password Silar123!. Gunakan email fiktif lain untuk mencoba pendaftaran; sesudah verifikasi masuk dengan password yang didaftarkan, dan sesudah reset gunakan password baru. Semua akun simulasi kembali ke awal saat refresh. Gunakan password contoh minimal 8 karakter. Aktivasi dan reset mengonsumsi OTP bersama penetapan password. Layanan nyata mengikuti validator backend dan parameter yang divalidasi.</p><h2>Perangkat sasaran SLR_07</h2><p>Layout acuan: ponsel 390 × 844 dan desktop 1366 × 768; diperluas dengan CSS responsif. Sasaran yang ditetapkan: Chrome Android serta Chrome/Edge Windows. Catat perangkat, versi browser dan hasil pemeriksaan sebenarnya; penetapan sasaran belum membuktikan kompatibilitas lulus.</p><h2>Dokumentasi kelompok</h2><p><a href="README.md" download>Unduh docs/uiux/README.md</a> · <a href="screens.json" download>Unduh pemetaan layar dan kebutuhan</a> · <a href="review-checklist.md" download>Unduh checklist review</a> · <a href="test-plan.md" download>Unduh langkah pengujian</a> · <a href="review-results.md" download>Unduh lembar hasil review</a> · <a href="submission.md" download>Unduh panduan pengumpulan</a> · <a href="review-next-steps.md" download>Unduh langkah review tersisa</a> · <a href="penempatan-berkas.md" download>Unduh petunjuk penempatan berkas</a> · <a href="technical-review.md" download>Unduh hasil pemeriksaan teknis</a></p><p>Review pengguna U07-01–U07-10 sudah dicatat. U07-11–U07-15 lulus pemeriksaan teknis tambahan; konten awareness U07-16 diperiksa sebagian. Login dan urutan publikasi diperbaiki. Finalisasi manual perangkat/usability, uji ulang akun dan keputusan kelompok masih perlu dicatat. Baca lembar hasil review sebelum mencentang task SLR_07.</p></div>`;}
function body(){if(s.page==='GUIDE')return guide();if(s.offline)return offline();if(s.scenario==='ACCESS_DENIED')return denied();if(s.page.startsWith('AK'))return auth();if(s.page==='RP01')return listPage('owned');if(s.page==='RP02')return compose();if(s.page==='RP03')return processPage();if(s.page==='RP04')return verify();if(s.page==='RP05'||s.page==='OP03'||s.page==='OP04')return detail();if(s.page==='OP01')return listPage('queue');if(s.page==='OP02')return listPage('assigned');if(s.page==='OP05')return publication();if(s.page.startsWith('AD'))return admin();if(s.page==='PB01')return publicList();if(s.page==='PB02')return publicDetail();if(s.page==='UM01')return notifications();if(s.page==='UM02')return pwaPage();if(s.page==='ABOUT')return heading('Tentang','SILAR','Sistem Inteligensi Laporan Adaptif dan Responsif')+`<div class="card"><p class="narrative">SILAR membantu masyarakat menyusun laporan kejadian dari teks, audio, gambar, atau kombinasinya. Pelapor memeriksa hasil sebelum pengiriman resmi. Operator meninjau laporan, mencatat tindak lanjut, serta menyetujui informasi yang aman dipublikasikan.</p>${helper('Cakupan MVP: kebakaran, banjir, gempa bumi, dan kecelakaan. AI tidak memastikan kebenaran di lapangan atau mengerahkan petugas otomatis.')}</div>`;return denied();}
function modalHTML(){if(!modal)return '';const r=current(s);let title='',content='',form='';if(modal==='fields'){title='Koreksi informasi';content=field('location','Lokasi',r.card.location)+field('time','Waktu yang disebut',r.card.time)+field('occurredAt','Waktu pasti, jika diketahui',r.card.occurredAt,'placeholder="Kosongkan jika sumber tidak menentukan waktu pasti"')+area('impact','Dampak',r.card.impact)+area('victims','Informasi korban',r.card.victims,'Kosong bukan berarti korban pasti nol.')+field('parties','Pihak terlibat',r.card.parties)+field('objects','Objek terdampak',r.card.objects)+helper('Kategori hasil AI tidak diubah melalui koreksi field. Konfirmasi baru diperlukan untuk versi baru.');form='fields-form';}if(modal==='narrative'){title='Revisi narasi';content=area('text','Narasi yang diperiksa',r.card.narrative)+helper('Perubahan ini memerlukan analisis ulang SENA, NARA, dan Fusion, serta konfirmasi versi baru.');form='narrative-form';}if(modal==='review'){title='Catat pemeriksaan';content=`<div class="field"><label for="outcome">Hasil pemeriksaan</label><select id="outcome" name="outcome"><option value="VALID">Valid</option><option value="INVALID">Tidak valid</option><option value="INCONCLUSIVE">Belum dapat dipastikan</option></select></div>`+area('reason','Alasan pemeriksaan','','Alasan merupakan catatan internal dan tidak dibuka kepada Reporter.');form='review-form';}if(modal==='followup'){title='Catat tindak lanjut';content=area('description','Tindakan atau perkembangan')+helper('Pencatatan ini tidak mengirim pertanyaan tambahan kepada Reporter.');form='followup-form';}if(modal==='decision'){title='Keputusan internal atau publikasi';content=`<div class="field"><label for="decision">Arah keputusan</label><select id="decision" name="decision"><option value="INTERNAL">Tetap internal</option><option value="PREPARE" ${r.validation!=='VALID'?'disabled':''}>Lanjutkan persiapan publikasi</option></select></div>`+area('reason','Alasan keputusan')+helper('Persiapan publikasi belum membentuk kandidat atau menerbitkan informasi.');form='decision-form';}if(modal==='cancel'){title='Batalkan kandidat aktif';content=area('reason','Alasan pembatalan')+helper('Kandidat disimpan sebagai CANCELLED. Versi yang sudah terbit tetap tersedia.','amber');form='cancel-form';}if(modal==='close'){title='Tutup penanganan laporan';content=area('note','Catatan penutupan')+helper('Syarat: review tersedia, tindak lanjut selesai/dibatalkan, keputusan internal atau terbit, dan tidak ada kandidat aktif. CLOSED menolak perubahan berikutnya.','amber');form='close-form';}if(modal==='assign'){title='Penugasan atau pengalihan';content=`<div class="field"><label for="target">Operator tujuan</label><select name="operator" id="target"><option value="op-a">Operator A</option><option value="op-b">Operator B</option></select></div>`+area('reason','Alasan penugasan / pengalihan')+helper('Pengalihan mencabut akses penanganan Operator lama. Riwayat tetap disimpan.');form='assign-form';}if(modal==='record'){title='Rekam suara';content=`<div class="recording">${icon('mic')}<div class="time">00:12</div><p class="subtitle">Tampilan rekaman contoh. Mikrofon perangkat tidak diakses.</p></div>`;form='record-form';}if(modal==='newop'){title='Buat akun Operator';content=field('name','Nama lengkap')+field('email','Email','','type="email"')+`${permissionFields()}`+helper('Akun awal belum aktif. Pemilik menerima email aktivasi dan menetapkan password sendiri.');form='newop-form';}if(modal==='manageop'){const o=s.operators.find(o=>o.id===s.editOperatorId);title='Kelola akun Operator';content=field('name','Nama lengkap',o.name)+`<label class="checkline"><input type="checkbox" ${o.active?'checked':''} name="active" ${!o.verified?'disabled':''}> Akun aktif</label>`+permissionFields(o.permissions)+helper('Akun belum diaktivasi harus diaktifkan oleh pemilik melalui email. Riwayat tetap dipertahankan.');form='manageop-form';}
if(modal==='finishfollowup'){title='Batalkan tindak lanjut';content=area('reason','Alasan pembatalan')+helper('Alasan nonkosong wajib dicatat. Tindak lanjut dipertahankan sebagai riwayat.');form='finishfollowup-form';}
if(modal==='email'){title='Email contoh untuk review';content=`<p class="subtitle">Simulasi email, bukan pengiriman nyata. Kode uji: <strong>123456</strong>.</p><p class="hint">Tautan membawa challenge_id saja, tanpa kode atau password.</p><div class="inline-actions">${btn('Verifikasi Email','nav','data-page="AK03"','small')}${btn('Aktivasi Operator','nav','data-page="AK04"','small')}${btn('Reset Password','nav','data-page="AK06"','small')}</div>`;form='email-form';}
return `<div class="modal-wrap" data-backdrop="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${title}</h2>${btn('×','dismiss-modal','aria-label="Tutup dialog"')}</div>${s.notice?.type==='error'?`<div class="notice error" role="alert">${esc(s.notice.message)}</div>`:''}<form id="${form}">${content}<div class="actions">${btn('Kembali','dismiss-modal')}<button class="primary">${modal==='record'?'Gunakan Rekaman Contoh':'Simpan / Lanjutkan'}</button></div></form></section></div>`;}
function render(){const error=s.notice;$('#app').innerHTML=lab()+`<div class="app-frame ${menuOpen?'menu-open':''}"><div class="mobile-overlay" data-action="menu"></div>${sidebar()}<div class="work-area"><header class="topline"><div class="inline-actions">${btn('☰','menu','aria-label="Buka navigasi"','mobile-menu')}<strong>Sistem Inteligensi Laporan Adaptif dan Responsif</strong></div><div class="topline-right"><span class="screen-code">${s.page}</span><span>${s.offline?'Offline · simulasi':'Data contoh'}</span></div></header><main class="content" id="main-content">${error?`<div class="notice ${error.type}" role="status"><div>${esc(error.message)}${error.code?`<code>${esc(error.code)}</code>`:''}</div>${btn('×','dismiss-notice','aria-label="Tutup pesan"')}</div>`:''}${body()}<div class="footer-note">SILAR · Prototype SLR_07 · Tidak mengirim laporan, email, atau data ke layanan AI.</div></main></div></div>`+modalHTML();if(modal)requestAnimationFrame(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus());}
function perform(action,p={}){try{act(s,action,p);render();return true;}catch(e){notice(s,e.message,'error',e.code||'ERROR');render();return false;}}
function runAnalysis(revision=false){if(!perform(revision?'ANALYSE_REVISION':'ANALYSE'))return;const id=s.selectedId,scenario=current(s).run.scenario;if(['RUNNING','UNKNOWN'].includes(scenario))return;setTimeout(()=>{const prevId=s.selectedId,prevPage=s.page;s.selectedId=id;try{act(s,'FINISH');if(prevId!==id||prevPage!=='RP03'){s.selectedId=prevId;s.page=prevPage;}}catch(e){notice(s,e.message,'error',e.code);}render();},1000);}
document.addEventListener('input',e=>{if(e.target.id==='report-text'){try{act(s,'TEXT',{value:e.target.value});}catch{}}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){act(s,'SCENARIO',{value:e.target.value});render();}else if(e.target.id==='operator-person'){s.operator=e.target.value;s.page='OP01';render();}else if(e.target.id==='admin-private'){s.adminPrivate=e.target.checked;render();}else if(e.target.dataset.evidence){perform('SELECT',{id:e.target.dataset.evidence,checked:e.target.checked});}else if(e.target.id==='sanitization-check'){s.publicationChecked=e.target.checked;render();}else if(['image-file','audio-file'].includes(e.target.id)){for(const f of e.target.files){if(e.target.id==='image-file'&&!['image/png','image/jpeg'].includes(f.type)){notice(s,'Pilih gambar PNG atau JPEG.','error','MEDIA_UNSUPPORTED');continue;}act(s,'ADD_FILE',{name:f.name,type:e.target.id==='image-file'?'IMAGE':'AUDIO',mime:f.type,size:f.size,preview:e.target.id==='image-file'?URL.createObjectURL(f):null});}render();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{if(a==='role'){act(s,'ROLE',{role:el.dataset.role});menuOpen=false;modal=null;}else if(a==='nav'){act(s,'NAV',{page:el.dataset.page,id:el.dataset.id});menuOpen=false;modal=null;}else if(a==='new-report'){const draft=s.reports.find(r=>r.owner==='reporter'&&r.workflow==='NOT_SUBMITTED');if(draft){s.selectedId=draft.id;s.page='RP02';}else{const temp=initial().reports[0];temp.id=uid(s.nextId++);s.reports.unshift(temp);s.selectedId=temp.id;s.page='RP02';}}else if(a==='open-report'){s.selectedId=el.dataset.id;const r=current(s);s.page=r.workflow==='NOT_SUBMITTED'?(r.card?'RP04':'RP02'):s.role==='operator'?'OP03':'RP05';}else if(a==='sample')act(s,'SAMPLE');else if(a==='save')act(s,'SAVE');else if(a==='analyse'){runAnalysis();return;}else if(a==='analyse-revision'){runAnalysis(true);return;}else if(a==='read-status')act(s,'READ_STATUS');else if(a==='tech-recover')act(s,'TECH_RECOVER');else if(a==='confirm')act(s,'CONFIRM');else if(a==='submit')act(s,'SUBMIT');else if(a==='claim'){s.selectedId=el.dataset.id;act(s,'CLAIM');}else if(a==='edit-fields')modal='fields';else if(a==='edit-narrative')modal='narrative';else if(a==='review')modal='review';else if(a==='followup')modal='followup';else if(a==='decision'){s.page='OP04';modal='decision';}else if(a==='cancel-candidate')modal='cancel';else if(a==='close')modal='close';else if(a==='assign')modal='assign';else if(a==='record')modal='record';else if(a==='new-operator')modal='newop';else if(a==='manage-operator'){s.editOperatorId=el.dataset.id;modal='manageop';}else if(a==='resend-activation')act(s,'RESEND_ACTIVATION',{id:el.dataset.id});else if(a==='approve')act(s,'APPROVE');else if(a==='publish')act(s,'PUBLISH');else if(a==='finish-followup'){if(el.dataset.status==='CANCELLED'){s.cancelFollowupId=Number(el.dataset.id);modal='finishfollowup';}else act(s,'FINISH_FOLLOWUP',{id:Number(el.dataset.id),status:'DONE'});}else if(a==='pick-image'){$('#image-file').click();return;}else if(a==='pick-audio'){$('#audio-file').click();return;}else if(a==='tab')listTab=el.dataset.tab;else if(a==='mark-read')act(s,'MARK_READ',{id:Number(el.dataset.id)});else if(a==='open-notification'){const n=s.notifications.find(n=>n.id===Number(el.dataset.id));act(s,'MARK_READ',{id:n.id});s.selectedId=n.reportId;s.page=s.role==='operator'?'OP03':'RP05';}else if(a==='resend'){s.resendSeconds=60;notice(s,'Jika memenuhi syarat, petunjuk terbaru dikirim melalui email. Gunakan tautan terbaru.','info');clearInterval(resendTimer);resendTimer=setInterval(()=>{s.resendSeconds=Math.max(0,s.resendSeconds-1);const b=document.querySelector('[data-action="resend"]');if(b){b.disabled=s.resendSeconds>0;b.textContent=s.resendSeconds?'Kirim ulang dalam '+s.resendSeconds+' dtk':'Kirim ulang kode';}if(!s.resendSeconds)clearInterval(resendTimer);},1000);}else if(a==='demo-email')modal='email';else if(a==='install-demo')notice(s,'Prototype memperagakan panduan instalasi. Untuk aplikasi, ikuti menu instalasi dari browser yang mendukung.','info');else if(a==='logout'){s.role='account';s.page='AK01';notice(s,'Anda keluar dari tampilan akun contoh.','info');}else if(a==='dismiss-notice')s.notice=null;else if(a==='dismiss-modal')modal=null;else if(a==='menu')menuOpen=!menuOpen;else if(a==='guide')s.page='GUIDE';else if(a==='reset'){s=initial();modal=null;listTab='all';publicFilter={q:'',category:'',location:''};}else if(a==='refresh')notice(s,'Daftar contoh dibaca ulang. Tidak ada polling atau push otomatis.','info');render();}catch(e2){notice(s,e2.message,'error',e2.code||'ERROR');render();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,p=Object.fromEntries(new FormData(f));const actions={'fields-form':'REVISE_FIELDS','narrative-form':'REVISE_NARRATIVE','review-form':'REVIEW','followup-form':'FOLLOWUP','decision-form':'DECISION','cancel-form':'CANCEL_CANDIDATE','close-form':'CLOSE','assign-form':'ASSIGN','auth-form':'AUTH','profile-form':'PROFILE'};if(f.id==='public-filter'){publicFilter={q:p.q,category:p.category,location:p.location};render();return;}if(f.id==='publication-form'){if(perform('CREATE_CANDIDATE',{data:p}))modal=null;render();return;}if(f.id==='record-form'){perform('ADD_FILE',{name:'Rekaman contoh · bukan rekaman perangkat',type:'AUDIO',mime:'Format mengikuti decoder integrasi',size:0});modal=null;render();return;}if(['newop-form','manageop-form'].includes(f.id)){const permissions=new FormData(f).getAll('permissions');const before=modal;modal=null;const ok=f.id==='newop-form'?perform('CREATE_OPERATOR',{name:p.name,email:p.email,permissions}):perform('PATCH_OPERATOR',{id:s.editOperatorId,name:p.name,active:p.active==='on',permissions});if(!ok)modal=before;render();return;}if(f.id==='finishfollowup-form'){modal=null;perform('FINISH_FOLLOWUP',{id:s.cancelFollowupId,status:'CANCELLED',reason:p.reason});return;}if(f.id==='email-form'){modal=null;render();return;}if(actions[f.id]){const before=modal;modal=null;if(!perform(actions[f.id],p)){modal=before;render();}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){modal=null;menuOpen=false;render();}if(e.key==='Tab'&&modal){const els=[...document.querySelectorAll('.modal button:not([disabled]),.modal input:not([disabled]),.modal textarea,.modal select')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();
